local SECRET_SALT = "ZIRO_HUB_RIOT_SECRET_SALT_2026"
local MASTER_KEY = "ZIRO-MASTER-RIOT-2026"
local SAVE_FILE_NAME = "ziro_key.txt"

-- Services
local TweenService = game:GetService("TweenService")
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local localPlayer = Players.LocalPlayer

-- Detect Parent GUI
local function getSafeGuiParent()
    local success, parent = pcall(function()
        if type(gethui) == "function" then
            local hui = gethui()
            if hui and typeof(hui) == "Instance" then return hui end
        end
        return CoreGui
    end)
    if success and parent then return parent end
    return localPlayer:WaitForChild("PlayerGui")
end

-- Pure Luau Bit32 SHA-256 for Key Signature Verification
local _b32 = bit32 or bit
local band, bor, bxor, bnot = _b32.band, _b32.bor, _b32.bxor, _b32.bnot
local rshift, lshift = _b32.rshift, _b32.lshift
local rrotate = _b32.rrotate or function(a, b) return bor(rshift(a, b), lshift(a, 32 - b)) end

local SHA256_K = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
}

local function computeSHA256(str)
    if syn and syn.crypt and syn.crypt.hash then return syn.crypt.hash(str) end
    if crypt and crypt.hash then return crypt.hash(str, "sha256") end

    local H = {
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    }

    local len = #str
    local pad = { string.byte(str, 1, len) }
    pad[#pad + 1] = 0x80
    while (#pad % 64) ~= 56 do pad[#pad + 1] = 0 end

    local bitlen = len * 8
    for i = 7, 0, -1 do
        pad[#pad + 1] = band(rshift(bitlen, i * 8), 0xff)
    end

    local W = {}
    for i = 1, #pad, 64 do
        for t = 0, 15 do
            W[t] = bor(lshift(pad[i + t*4], 24), lshift(pad[i + t*4 + 1], 16), lshift(pad[i + t*4 + 2], 8), pad[i + t*4 + 3])
        end
        for t = 16, 63 do
            local s0 = bxor(rrotate(W[t - 15], 7), rrotate(W[t - 15], 18), rshift(W[t - 15], 3))
            local s1 = bxor(rrotate(W[t - 2], 17), rrotate(W[t - 2], 19), rshift(W[t - 2], 10))
            W[t] = band(W[t - 16] + s0 + W[t - 7] + s1, 0xffffffff)
        end

        local a, b, c, d, e, f, g, h = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
        for t = 0, 63 do
            local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
            local ch = bxor(band(e, f), band(bnot(e), g))
            local temp1 = band(h + S1 + ch + SHA256_K[t + 1] + W[t], 0xffffffff)
            local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
            local maj = bxor(band(a, b), band(a, c), band(b, c))
            local temp2 = band(S0 + maj, 0xffffffff)

            h = g
            g = f
            f = e
            e = band(d + temp1, 0xffffffff)
            d = c
            c = b
            b = a
            a = band(temp1 + temp2, 0xffffffff)
        end

        H[1] = band(H[1] + a, 0xffffffff)
        H[2] = band(H[2] + b, 0xffffffff)
        H[3] = band(H[3] + c, 0xffffffff)
        H[4] = band(H[4] + d, 0xffffffff)
        H[5] = band(H[5] + e, 0xffffffff)
        H[6] = band(H[6] + f, 0xffffffff)
        H[7] = band(H[7] + g, 0xffffffff)
        H[8] = band(H[8] + h, 0xffffffff)
    end

    local hex = ""
    for _, val in ipairs(H) do
        hex = hex .. string.format("%08x", val)
    end
    return hex:upper()
end

-- Validate Key Signature (Independent of HWID)
local function validateKey(inputKey)
    local clean = inputKey:gsub("%s+", ""):upper()
    if clean == MASTER_KEY or clean == "WOLFIE-MASTER-RIOT-2026" then
        return true, "MASTER KEY AUTORIZADA"
    end
    local parts = string.split(clean, "-")
    if #parts ~= 4 or parts[1] ~= "ZIRO" then
        return false, "FORMATO INVALIDO (USE: ZIRO-XXXX-XXXX-XXXX)"
    end
    local token = parts[2] .. "-" .. parts[3]
    local sig = parts[4]
    local hash = computeSHA256(token .. ":" .. SECRET_SALT)
    local expectedSig = string.sub(hash, 1, 4)
    if sig == expectedSig then
        return true, "CHAVE AUTORIZADA"
    end
    return false, "CHAVE RECUSADA / INVALIDA"
end

