	""
}

local function _0x_decode(_0x_data, _0x_k)
	local _0x_len = #_0x_data
	local _0x_out = {}
	local _0x_idx = 1
	local _bxor = _b32.bxor
	local _lshift = _b32.lshift
	local _rshift = _b32.rshift
	local _bor = _b32.bor
	local _band = _b32.band
	local _schar = string.char
	local _sbyte = string.byte

	local _0x_i = 1
	while _0x_i <= _0x_len do
		local _c1 = _0x_map[_sbyte(_0x_data, _0x_i)] or 0
		local _c2 = _0x_map[_sbyte(_0x_data, _0x_i + 1)] or 0
		local _b3 = _sbyte(_0x_data, _0x_i + 2)
		local _b4 = _sbyte(_0x_data, _0x_i + 3)
		local _c3 = _0x_map[_b3] or 0
		local _c4 = _0x_map[_b4] or 0

		local _n = _bor(_lshift(_c1, 18), _lshift(_c2, 12), _lshift(_c3, 6), _c4)

		_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 16), 255), _0x_k))
		_0x_idx = _0x_idx + 1

		if _b3 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 8), 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		if _b4 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_n, 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		_0x_i = _0x_i + 4
	end
	return table.concat(_0x_out)
end

local function launchCoreScript()
    local segments = {}
    for idx, c in ipairs(_0x_chunks) do
        segments[idx] = _0x_decode(c, _0x_key)
    end
    local source = table.concat(segments)
    local fn, err = (loadstring or load)(source)
    if not fn then
        warn("[Ziro Hub Gateway] Falha ao compilar payload: " .. tostring(err))
        return
    end
    return fn()
end

