-- MODERN PURPLE KEY UI (RGB 245, 0, 237)
-- ============================================================================
local function createKeyUI()
    local existing = getSafeGuiParent():FindFirstChild("ZiroHubKeyGateway")
    if existing then existing:Destroy() end

    local ScreenGui = Instance.new("ScreenGui")
    ScreenGui.Name = "ZiroHubKeyGateway"
    ScreenGui.ResetOnSpawn = false
    ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    ScreenGui.Parent = getSafeGuiParent()

    local Main = Instance.new("Frame")
    Main.Name = "MainFrame"
    Main.Size = UDim2.new(0, 420, 0, 250)
    Main.Position = UDim2.new(0.5, -210, 0.5, -125)
    Main.BackgroundColor3 = Color3.fromRGB(16, 12, 24)
    Main.BorderSizePixel = 0
    Main.Active = true
    Main.Draggable = true
    Main.Parent = ScreenGui

    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 12)
    Corner.Parent = Main

    local Stroke = Instance.new("UIStroke")
    Stroke.Color = Color3.fromRGB(245, 0, 237)
    Stroke.Thickness = 2
    Stroke.Parent = Main

    -- Top Header
    local Title = Instance.new("TextLabel")
    Title.Size = UDim2.new(1, -20, 0, 32)
    Title.Position = UDim2.new(0, 10, 0, 14)
    Title.BackgroundTransparency = 1
    Title.Font = Enum.Font.GothamBold
    Title.Text = "ZIRO HUB | BLOX FRUITS"
    Title.TextColor3 = Color3.fromRGB(255, 245, 255)
    Title.TextSize = 16
    Title.TextXAlignment = Enum.TextXAlignment.Center
    Title.Parent = Main

    local SubTitle = Instance.new("TextLabel")
    SubTitle.Size = UDim2.new(1, -20, 0, 18)
    SubTitle.Position = UDim2.new(0, 10, 0, 44)
    SubTitle.BackgroundTransparency = 1
    SubTitle.Font = Enum.Font.Gotham
    SubTitle.Text = "Autenticação de Acesso • Ziro Hub Oficial"
    SubTitle.TextColor3 = Color3.fromRGB(180, 140, 195)
    SubTitle.TextSize = 11
    SubTitle.TextXAlignment = Enum.TextXAlignment.Center
    SubTitle.Parent = Main

    -- Key Input Box
    local InputBox = Instance.new("TextBox")
    InputBox.Size = UDim2.new(1, -30, 0, 44)
    InputBox.Position = UDim2.new(0, 15, 0, 80)
    InputBox.BackgroundColor3 = Color3.fromRGB(26, 18, 38)
    InputBox.BorderSizePixel = 0
    InputBox.Font = Enum.Font.GothamMedium
    InputBox.PlaceholderText = "Cole sua chave Ziro aqui (ZIRO-XXXX...)"
    InputBox.PlaceholderColor3 = Color3.fromRGB(140, 100, 155)
    InputBox.Text = ""
    InputBox.TextColor3 = Color3.fromRGB(255, 255, 255)
    InputBox.TextSize = 13
    InputBox.ClearTextOnFocus = false
    InputBox.Parent = Main

    local InputCorner = Instance.new("UICorner")
    InputCorner.CornerRadius = UDim.new(0, 8)
    InputCorner.Parent = InputBox

    local InputStroke = Instance.new("UIStroke")
    InputStroke.Color = Color3.fromRGB(90, 40, 110)
    InputStroke.Thickness = 1
    InputStroke.Parent = InputBox

    -- Status Message Label
    local StatusLabel = Instance.new("TextLabel")
    StatusLabel.Size = UDim2.new(1, -30, 0, 24)
    StatusLabel.Position = UDim2.new(0, 15, 0, 132)
    StatusLabel.BackgroundTransparency = 1
    StatusLabel.Font = Enum.Font.Gotham
    StatusLabel.Text = "Aguardando chave de acesso..."
    StatusLabel.TextColor3 = Color3.fromRGB(170, 140, 185)
    StatusLabel.TextSize = 11
    StatusLabel.Parent = Main

    -- Auto-Load Saved Key if exists
    pcall(function()
        if readfile and isfile and isfile(SAVE_FILE_NAME) then
            local saved = readfile(SAVE_FILE_NAME)
            if saved and saved ~= "" then
                InputBox.Text = saved:gsub("%s+", ""):upper()
                StatusLabel.Text = "Chave salva detectada no dispositivo."
                StatusLabel.TextColor3 = Color3.fromRGB(160, 220, 255)
            end
        end
    end)

    -- Enter Button
    local EnterBtn = Instance.new("TextButton")
    EnterBtn.Size = UDim2.new(1, -30, 0, 46)
    EnterBtn.Position = UDim2.new(0, 15, 0, 168)
    EnterBtn.BackgroundColor3 = Color3.fromRGB(245, 0, 237)
    EnterBtn.Font = Enum.Font.GothamBold
    EnterBtn.Text = "VERIFICAR & ENTRAR"
    EnterBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    EnterBtn.TextSize = 13
    EnterBtn.BorderSizePixel = 0
    EnterBtn.Parent = Main

    local EnterCorner = Instance.new("UICorner")
    EnterCorner.CornerRadius = UDim.new(0, 8)
    EnterCorner.Parent = EnterBtn

    -- Close Button
    local CloseBtn = Instance.new("TextButton")
    CloseBtn.Size = UDim2.new(0, 24, 0, 24)
    CloseBtn.Position = UDim2.new(1, -30, 0, 12)
    CloseBtn.BackgroundTransparency = 1
    CloseBtn.Font = Enum.Font.GothamBold
    CloseBtn.Text = "X"
    CloseBtn.TextColor3 = Color3.fromRGB(220, 80, 100)
    CloseBtn.TextSize = 14
    CloseBtn.Parent = Main

    CloseBtn.MouseButton1Click:Connect(function()
        ScreenGui:Destroy()
    end)

    -- Verification Logic
    local isVerifying = false
    local function executeVerification()
        if isVerifying then return end
        isVerifying = true

        local inputKey = InputBox.Text:gsub("%s+", ""):upper()
        if inputKey == "" then
            StatusLabel.Text = "Erro: Digite uma chave valida!"
            StatusLabel.TextColor3 = Color3.fromRGB(255, 80, 80)
            isVerifying = false
            return
        end

        StatusLabel.Text = "Autenticando chave..."
        StatusLabel.TextColor3 = Color3.fromRGB(255, 220, 120)
        task.wait(0.2)

        local ok, msg = validateKey(inputKey)
        if ok then
            StatusLabel.Text = msg .. "! Iniciando Ziro Hub..."
            StatusLabel.TextColor3 = Color3.fromRGB(80, 255, 140)

            pcall(function()
                if writefile then
                    writefile(SAVE_FILE_NAME, inputKey)
                end
            end)

            task.wait(0.5)
            local tween = TweenService:Create(Main, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, -210, 0.45, -125)
            })
            tween:Play()
            tween.Completed:Connect(function()
                ScreenGui:Destroy()
                task.spawn(launchCoreScript)
            end)
        else
            StatusLabel.Text = msg
            StatusLabel.TextColor3 = Color3.fromRGB(255, 80, 80)
            isVerifying = false
        end
    end

    EnterBtn.MouseButton1Click:Connect(executeVerification)
    InputBox.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            executeVerification()
        end
    end)
end

-- Launch Gateway UI
createKeyUI()
